    return [frozenset(shape)]


def nearby_groups(grid, color):
    h, w = len(grid), len(grid[0])
    remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
    groups = []
    while remaining:
        group = {remaining.pop()}
        changed = True
        while changed:
            changed = False
            for p in list(remaining):
                if any(max(abs(p[0]-q[0]), abs(p[1]-q[1])) <= 2 for q in group):
                    group.add(p)
                    remaining.remove(p)
                    changed = True
        groups.append(group)
    return groups


def nearby_groups(points, distance=2):
    remaining = set(points)
    groups = []
    while remaining:
        group = {remaining.pop()}
        changed = True
        while changed:
            changed = False
            for p in list(remaining):
                if any(max(abs(p[0]-q[0]), abs(p[1]-q[1])) <= distance for q in group):
                    group.add(p)
                    remaining.remove(p)
                    changed = True
        groups.append(group)
    return groups


def placement(points, shapes):
    candidates = []
    for oi, shape in enumerate(shapes):
        for r, c in points:
            for mr, mc in shape:
                ar, ac = r - mr, c - mc
                if all((pr - ar, pc - ac) in shape for pr, pc in points):
                    candidates.append((oi, ar, ac))
    return min(candidates) if candidates else None


def paint(result, color, placed, shapes, h, w):
    oi, ar, ac = placed
    for mr, mc in shapes[oi]:
        rr, cc = ar + mr, ac + mc
        if 0 <= rr < h and 0 <= cc < w:
            result[rr][cc] = color


def transform(grid):
    h, w = len(grid), len(grid[0])
    fours = components(grid, 4)
    if not fours:
        return [row[:] for row in grid]
    motif_abs = max(fours, key=len)
    minr = min(r for r, c in motif_abs)
    minc = min(c for r, c in motif_abs)
    motif = {(r - minr, c - minc) for r, c in motif_abs}
    shapes = orientations(motif)
    result = [row[:] for row in grid]
    for color in range(10):
        if color in (1, 4):
            continue
        points = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for group in nearby_groups(points):
            placed = placement(group, shapes)
            if placed:
                paint(result, color, placed, shapes, h, w)
            else:
                # A loose cluster may contain more than one independent fragment.
                # Complete the connected fragments only when each matches the stencil.
                for part in components([[color if (r, c) in group else 1 for c in range(w)] for r in range(h)], color):
                    placed = placement(part, shapes)
                    if placed:
                        paint(result, color, placed, shapes, h, w)
    return result

